export function deferred<T = void>() {
  let resolve"'!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function trackD1(db: D1Database, calls: StoreCalls): D1Database {
  return new Proxy(db, {
    get(target, property) {
      const value = Reflect.get(target, property, target);
      if (typeof value !== "function") return value;
      return (...args: unknown[]) => {
        if (property === "prepare" || property === "batch" || property === "exec") calls.d1 += 1;
        return value.apply(target, args);
      };
    },
  }) as D1Database;
}

function trackR2(bucket: R2Bucket, calls: StoreCalls, faults: Faults): R2Bucket {
  return new Proxy(bucket, {
    get(target, property) {
      const value = Reflect.get(target, property, target);
      if (typeof value !== "function") return value;
      return async (...args: unknown[]) => {
        if (property === "head") {
          calls.head += 1;
          if (faults.failHead) throw new Error("injected head failure");
        }
        if (property === "get") {
          calls.get += 1;
          if (faults.failGet) throw new Error("injected get failure");
        }
        if (property === "put") {
          calls.put += 1;
          if (faults.failPut) throw new Error("injected put failure");
        }
        if (property === "list") {
          calls.list += 1;
          if (faults.failListAt?.has(calls.list)) throw new Error("injected list failure");
        }
        if (property === "delete") {
          calls.delete += 1;
          if (faults.failDelete) throw new Error("injected delete failure");
        }
        return value.apply(target, args);
      };
    },
  }) as R2Bucket;
